  const overrides = [];
  const home = [];
  const other = [];
  for (const [p, data2] of Object.entries(entries)) {
    if (p === "manifest.json") continue;
    const size = data2?.byteLength ?? data2?.length ?? 0;
    const rec = { path: p, size };
    if (p === "dspack.json" || p === "package.json" || p === "pnpm-workspace.yaml" || p === "pnpm-lock.yaml") machine.push(rec);
    else if (p.startsWith("overrides/")) overrides.push(rec);
    else if (p.startsWith("home/")) home.push(rec);
    else other.push(rec);
  }
  const byPath = (a, b3) => a.path.localeCompare(b3.path);
  machine.sort(byPath);
  overrides.sort(byPath);
  home.sort(byPath);
  other.sort(byPath);
