    const dest = managerDir(targetDir);
    let written = 0;
    for (const [entryPath, data2] of Object.entries(entries)) {
      const rel = entryPath.startsWith("package/") ? entryPath.slice("package/".length) : null;
      if (!rel || rel === "" || rel.endsWith("/")) continue;
      await fsp3.mkdir(path5.dirname(path5.join(dest, rel)), { recursive: true });
      await fsp3.writeFile(path5.join(dest, rel), data2);
      written += 1;
    }
